## repro's own command-line description with one more command, whose
## `default` is wrong-typed when compiled with `-d:csM6Wrong` (see
## `t_cs_m6_cli_model_type_checks_in_reprobuild_macros`). The program is
## generated by the same `reproProgramCode` the engine's is.
import std/macros

import confutils/clispec_config
import repro_cli_support/cli_description
from repro_cli_support/cli_program import reproProgramCode

const csM6Default = (when defined(csM6Wrong): "four" else: 4)

macro csM6Program() =
  var body = reproCommandLineDescription()
  body.add(quote do:
    subcmd "cs-m6-probe":
      flag jobs is int, default = csM6Default # CHECK
  )
  reproProgramCode(parseCliModel[NoCliExtension, ReproCommandLineParamExt](
    body, NoCliExtension()))

csM6Program()
